from typing import List, Dict


def _make_question(
    q_id: str,
    question: str,
    options: List[str],
    answer: int,
    explanation: str,
    difficulty: str = "medium",
    topic: str = "综合分析"
) -> Dict:
    """构造标准题目"""
    return {
        "id": q_id,
        "type": "select",
        "question": question,
        "options": options,
        "answer": answer,
        "explanation": explanation,
        "difficulty": difficulty,
        "topic": topic,
    }


